import { API_BASE_PATH } from "./api";
import { SERVER_CODE_HEADER, serverKeyOf } from "./server-code";

/**
 * Server-code routes. They are not in the generated client yet (the contract is regenerated by the coordinator), so
 * they go through `fetch` directly, with the same header and 401 handling as every other request.
 */

/** GET /server-code/check with the key of a candidate code (not yet stored). True only for 204. */
export async function checkServerCode(code: string): Promise<boolean> {
  const key = serverKeyOf(code);
  if (key === null) return false;
  try {
    const response = await globalThis.fetch(`${window.location.origin}${API_BASE_PATH}/server-code/check`, {
      headers: { [SERVER_CODE_HEADER]: key },
      credentials: "same-origin",
    });
    return response.status === 204;
  } catch {
    return false;
  }
}
